def comb_sort(nums):
    gap = len(nums)
    shrink_factor = 1.3
    sorted_flag = False

    while not sorted_flag:
        gap = int(gap / shrink_factor)
        if gap > 1:
            sorted_flag = True

        for i in range(len(nums) - gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                sorted_flag = False

    return nums
```

